from qgis.PyQt.QtWidgets import QAction

mw = iface.mainWindow()
out = []
for a in mw.findChildren(QAction):
    t = (a.text() or '')
    tt = (a.toolTip() or '')
    if 'プロパティ' in t or 'プロパティ' in tt or 'propert' in t.lower() or 'propert' in tt.lower():
        try:
            objs = a.associatedObjects()
        except Exception:
            objs = []
        out.append({
            'objectName': a.objectName(),
            'text': t,
            'tooltip': tt,
            'enabled': a.isEnabled(),
            'visible': a.isVisible(),
            'associated': [type(w).__name__ + ':' + (w.objectName() or '') for w in objs],
            'parent': type(a.parent()).__name__ + ':' + (a.parent().objectName() if a.parent() else ''),
        })
result = out
"}

