from qgis.PyQt.QtWidgets import QAction, QDockWidget

mw = iface.mainWindow()
out = []
for a in mw.findChildren(QAction):
    if a.objectName() == 'mActionPropertiesWidget':
        # どのドックに属するか
        p = a.parent()
        dock = None
        while p is not None:
            if isinstance(p, QDockWidget):
                dock = p
                break
            p = p.parent()
        out.append({
            'dock': dock.objectName() if dock else '?',
            'dock_visible': dock.isVisible() if dock else None,
            'checkable': a.isCheckable(),
            'checked': a.isChecked(),
            'enabled': a.isEnabled(),
        })
result = out
"}

