from qgis.PyQt.QtWidgets import QAction, QDockWidget

mw = iface.mainWindow()
done = None
for a in mw.findChildren(QAction):
    if a.objectName() == 'mActionPropertiesWidget':
        p = a.parent()
        dock = None
        while p is not None:
            if isinstance(p, QDockWidget):
                dock = p
                break
            p = p.parent()
        if dock is not None and dock.isVisible():
            a.trigger()
            done = {'dock': dock.objectName(), 'checked_now': a.isChecked()}
            break
result = done
